import React, {useEffect, useState} from 'react';
import './App.css';
const API='http://localhost:8080/api/listings';
const blank={donorName:'',foodItem:'',quantityServings:'',shelfLifeHours:'',location:''};
export default function App(){
 const [form,setForm]=useState(blank),[rows,setRows]=useState([]),[error,setError]=useState('');
 const load=async()=>{try{const r=await fetch(API);if(!r.ok)throw Error('Cannot load listings');setRows(await r.json());setError('');}catch(e){setError('Backend unavailable. Start Spring Boot on port 8080.');}};
 useEffect(()=>{load();},[]);
 const request=async(url,options)=>{try{const r=await fetch(url,options);if(!r.ok)throw Error(await r.text());await load();}catch(e){setError(e.message);}};
 const add=async e=>{e.preventDefault();try{const r=await fetch(API,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...form,quantityServings:Number(form.quantityServings)})});if(!r.ok)throw Error(await r.text());setForm(blank);await load();}catch(e){setError(e.message);}};
 return <main><header><span>♻ FOOD RESCUE</span><h1>Smart Food Rescue & Redistribution</h1><p>Share surplus food. Reduce waste. Support your community.</p></header><section className="stats"><div><strong>{rows.length}</strong><span>Total donations</span></div><div><strong>{rows.filter(x=>x.status==='AVAILABLE').length}</strong><span>Available</span></div><div><strong>{rows.filter(x=>x.status==='DELIVERED').length}</strong><span>Delivered</span></div></section><section className="panel"><h2>Post a Food Donation</h2><form onSubmit={add}>{Object.keys(blank).map(key=><label key={key}>{({donorName:'Donor / Restaurant',foodItem:'Food Item',quantityServings:'Quantity (servings)',shelfLifeHours:'Shelf Life',location:'Pickup Location'})[key]}<input required type={key==='quantityServings'?'number':'text'} min={key==='quantityServings'?1:undefined} value={form[key]} onChange={e=>setForm({...form,[key]:e.target.value})} placeholder={key==='shelfLifeHours'?'e.g. 5 hours':''}/></label>)}<button type="submit">+ Add Food Listing</button></form></section><section className="panel"><h2>Donation Listings</h2>{error&&<p className="error">{error}</p>}<div className="scroll"><table><thead><tr><th>Donor</th><th>Food</th><th>Servings</th><th>Shelf Life</th><th>Location</th><th>Status</th><th>Actions</th></tr></thead><tbody>{rows.length===0?<tr><td colSpan="7">No donations yet. Add the first one above!</td></tr>:rows.map(x=><tr key={x.id}><td>{x.donorName}</td><td>{x.foodItem}</td><td>{x.quantityServings}</td><td>{x.shelfLifeHours}</td><td>{x.location}</td><td><span className={'tag '+x.status}>{x.status}</span></td><td>{x.status!=='DELIVERED'&&<button className="action" onClick={()=>request(API+'/'+x.id,{method:'PUT'})}>{x.status==='AVAILABLE'?'Claim':'Deliver'}</button>}<button className="danger" onClick={()=>{if(window.confirm('Delete this donation?'))request(API+'/'+x.id,{method:'DELETE'});}}>Delete</button></td></tr>)}</tbody></table></div></section><footer>Demo project · Only list food that is safe to share and follow local food-safety guidance.</footer></main>;
}
